import{_ as i,o as a,c as o,ah as t}from"./chunks/framework.Sdx4l2LO.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap/index.md","filePath":"roadmap/index.md","lastUpdated":1774801192000}'),r={name:"roadmap/index.md"};function l(n,e,s,d,c,m){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>DINOForge follows a milestone-based development plan, building from low-level runtime to high-level content packs.</p><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2><h3 id="m0-—-reverse-engineering-harness" tabindex="-1">M0 — Reverse-Engineering Harness ✅ <a class="header-anchor" href="#m0-—-reverse-engineering-harness" aria-label="Permalink to &quot;M0 — Reverse-Engineering Harness :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Install BepInEx, confirm plugin loading, test plugin, dump entities.</p><ul><li>BepInEx 5.4.23.5 installed with modified Doorstop pre-loader</li><li>Runtime builds to <code>BepInEx/ecs_plugins/DINOForge.Runtime.dll</code></li><li>Entity Dumper, System Enumerator, Debug Overlay scaffolded</li><li>Initial test suite passing (xUnit + FluentAssertions)</li></ul><hr><h3 id="m1-—-runtime-scaffold" tabindex="-1">M1 — Runtime Scaffold ✅ <a class="header-anchor" href="#m1-—-runtime-scaffold" aria-label="Permalink to &quot;M1 — Runtime Scaffold :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Bootstrap plugin, version detection, logging, ECS introspection, debug overlay.</p><ul><li>BepInEx plugin bootstrap with version-aware initialization</li><li>ECS system and component discovery</li><li>Runtime logging infrastructure</li><li>Debug overlay foundation (F9 key)</li></ul><hr><h3 id="m2-—-generic-mod-sdk" tabindex="-1">M2 — Generic Mod SDK ✅ <a class="header-anchor" href="#m2-—-generic-mod-sdk" aria-label="Permalink to &quot;M2 — Generic Mod SDK :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Pack manifest format, registry system, schema validation, override model, dependency resolver.</p><ul><li>Pack manifest model with YAML loader (YamlDotNet)</li><li>Generic <code>Registry&amp;lt;T&amp;gt;</code> system with priority layers and conflict detection</li><li>Schema validation pipeline (NJsonSchema)</li><li>Content override model with 4-layer priority (BaseGame -&gt; Framework -&gt; DomainPlugin -&gt; Pack)</li><li>Dependency resolver with cycle detection</li><li>17 JSON/YAML schemas covering all content types</li><li>Content loader for YAML pack ingestion</li><li>Asset service with addressables catalog support</li></ul><hr><h3 id="m3-—-dev-tooling" tabindex="-1">M3 — Dev Tooling ✅ <a class="header-anchor" href="#m3-—-dev-tooling" aria-label="Permalink to &quot;M3 — Dev Tooling :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Pack compiler CLI, validator CLI, test harness, diff tools, diagnostics.</p><ul><li>PackCompiler CLI (validate, build, assets commands)</li><li>DumpTools CLI with Spectre.Console interactive terminal UI</li><li><code>dinoforge</code> CLI with 11 commands (status, query, override, reload, watch, dump, resources, screenshot, verify, component-map, etc.)</li><li>MCP Server with 13 game interaction tools for Claude Code integration</li></ul><hr><h3 id="m3-5-—-qa-harness" tabindex="-1">M3.5 — QA Harness ✅ <a class="header-anchor" href="#m3-5-—-qa-harness" aria-label="Permalink to &quot;M3.5 — QA Harness :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Bridge Protocol/Client for IPC, integration test suite, CI-runnable tests.</p><ul><li>Bridge Protocol: JSON-RPC message types, IGameBridge interface, typed result models</li><li>Bridge Client: GameClient for out-of-process game communication with connection state management</li><li>Integration test project (<code>DINOForge.Tests.Integration</code>) with assertions, fixtures, and test data</li><li>14 integration tests covering content loading, bridge communication, end-to-end pack application</li><li>CI solution (<code>DINOForge.CI.sln</code>) excluding Runtime for headless builds</li></ul><hr><h3 id="m4-—-warfare-domain-plugin" tabindex="-1">M4 — Warfare Domain Plugin ✅ <a class="header-anchor" href="#m4-—-warfare-domain-plugin" aria-label="Permalink to &quot;M4 — Warfare Domain Plugin :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Factions, doctrines, unit classes, weapons, waves, defenses.</p><ul><li>Faction archetype system (Order, Industrial Swarm, Asymmetric)</li><li>5 factions: Republic, CIS, West, Classic West Enemy, Guerrilla</li><li>Unit role matrix with 13 shared slots across all factions</li><li>Weapon classes (12 types) and defense tags (8 types)</li><li>Wave composition templates</li><li>Doctrine modifiers</li><li>Balance validation</li></ul><hr><h3 id="m5-—-first-example-packs" tabindex="-1">M5 — First Example Packs ✅ <a class="header-anchor" href="#m5-—-first-example-packs" aria-label="Permalink to &quot;M5 — First Example Packs :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>Full set of example packs demonstrating all content types.</p><ul><li><code>warfare-modern</code> — West vs Classic West Enemy (Modern Warfare theme)</li><li><code>warfare-starwars</code> — Republic vs CIS (Star Wars Clone Wars theme)</li><li><code>warfare-guerrilla</code> — Asymmetric warfare (Guerrilla faction)</li><li><code>example-balance</code> — Simple stat override balance mod</li><li><code>economy-balanced</code> — Economy balance profiles and trade rules</li><li><code>scenario-tutorial</code> — Tutorial scenario with scripted conditions</li></ul><hr><h3 id="m6-—-in-game-mod-menu-hmr" tabindex="-1">M6 — In-Game Mod Menu &amp; HMR ✅ <a class="header-anchor" href="#m6-—-in-game-mod-menu-hmr" aria-label="Permalink to &quot;M6 — In-Game Mod Menu &amp; HMR :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>F10 mod menu overlay, hot module replacement for YAML packs.</p><ul><li>Mod menu overlay (F10) with pack listing, enable/disable, manual reload</li><li>Mod settings panel for per-pack configuration</li><li>Pack file watcher (HMR) for live YAML reload during gameplay</li><li>Hot reload bridge wiring changes to re-validation and re-application</li></ul><hr><h3 id="m7-—-installer-universe-bible" tabindex="-1">M7 — Installer &amp; Universe Bible ✅ <a class="header-anchor" href="#m7-—-installer-universe-bible" aria-label="Permalink to &quot;M7 — Installer &amp; Universe Bible :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>PowerShell/Bash installer, Universe Bible system, pack generator.</p><ul><li><code>Install-DINOForge.ps1</code> (Windows) and <code>install.sh</code> (Linux/macOS) installer scripts</li><li>Installer library with programmatic installation support</li><li>Universe Bible system: faction taxonomies, naming guides, style guides, crosswalk dictionaries</li><li>Universe loader for parsing Bible documents</li><li>Pack generator for scaffolding total conversion packs from a Universe Bible</li></ul><p><strong>Completed 2026-03-15</strong>: Universe Bible system working, installers ready.</p><hr><h3 id="m8-—-runtime-integration-video-proof" tabindex="-1">M8 — Runtime Integration &amp; Video Proof ✅ <a class="header-anchor" href="#m8-—-runtime-integration-video-proof" aria-label="Permalink to &quot;M8 — Runtime Integration &amp; Video Proof :white_check_mark:&quot;">​</a></h3><p><strong>Status</strong>: Complete</p><p>ModPlatform orchestrator wiring SDK to Bridge to UI to HMR + autonomous video proof pipeline.</p><ul><li><code>ModPlatform</code> class owns entire mod platform lifecycle (ADR-009)</li><li>Lifecycle phases: Initialize -&gt; OnWorldReady -&gt; LoadPacks -&gt; StartHotReload -&gt; Shutdown</li><li>Plugin.cs stays thin (bootstrap only, forwards Unity callbacks)</li><li>ECS bridge with component mapping, stat modifiers, entity queries, override applicator</li><li>F9/F10 overlay regression fixed (2026-03-20): Removed Harmony patches, restored HideAndDontSave + DontDestroyOnLoad</li><li><strong>prove-features v2 pipeline (2026-03-27)</strong>: Remotion video rendering + Edge-TTS voiceover + OmniParser VLM validation <ul><li>4 MP4 proof videos rendered with captions and transitions</li><li>5 MP3 audio tracks with neural voice (Microsoft Aria)</li><li>OmniParser-based UI element detection for automatic screenshot validation</li><li>Evidence bundle: <code>docs/proof-of-features/20260327_213851/</code></li></ul></li></ul><p><strong>Completed 2026-03-27</strong>: End-to-end validation verified, F9/F10 working, video proof pipeline mature.</p><hr><h3 id="m9-—-desktop-companion" tabindex="-1">M9 — Desktop Companion ⌛ <a class="header-anchor" href="#m9-—-desktop-companion" aria-label="Permalink to &quot;M9 — Desktop Companion :hourglass:&quot;">​</a></h3><p><strong>Status</strong>: In Progress</p><p>WinUI 3 / WindowsAppSDK 1.6 desktop GUI that mirrors F9/F10 in-game panels for out-of-game evaluation.</p><ul><li>WinUI 3 + Mica background + NavigationView shell</li><li>Pack list view (mirrors F10 mod menu) with enable/disable toggle</li><li>Debug panel view (mirrors F9 panel) with 5 collapsible sections</li><li><code>disabled_packs.json</code> read/write parity with game</li><li>No game launch required for pack configuration evaluation</li><li>ADR-011</li></ul><hr><h3 id="m10-—-fuzzing-infrastructure" tabindex="-1">M10 — Fuzzing Infrastructure 🕒 <a class="header-anchor" href="#m10-—-fuzzing-infrastructure" aria-label="Permalink to &quot;M10 — Fuzzing Infrastructure :clock3:&quot;">​</a></h3><p><strong>Status</strong>: Planned</p><p>Comprehensive property-based and coverage-guided fuzzing across all serialization paths.</p><ul><li>FsCheck expanded from 4 domains / 14 properties to 10+ domains / 30+ properties</li><li>SharpFuzz coverage-guided fuzzing on YAML, JSON, semver, and PackManifest parsers</li><li>Persistent fuzz corpus (<code>src/Tests/FuzzCorpus/</code>)</li><li>Nightly CI fuzz gate (<code>.github/workflows/fuzz.yml</code>)</li><li>ADR-012</li></ul><hr><h3 id="m11-—-test-coverage-code-completion" tabindex="-1">M11 — Test Coverage + Code Completion 🕒 <a class="header-anchor" href="#m11-—-test-coverage-code-completion" aria-label="Permalink to &quot;M11 — Test Coverage + Code Completion :clock3:&quot;">​</a></h3><p><strong>Status</strong>: Planned</p><p>Fill test gaps and resolve build-excluded incomplete code items.</p><ul><li><code>AssetSwapRegistryTests</code>, <code>FileSystemPackRootResolverTests</code>, <code>PackFileWatcherIntegrationTests</code> added</li><li>Excluded test re-enablement (UnitSpawner, FactionSystem behind mock ECS)</li><li>Target: 130+ passing tests (up from ~80)</li><li><code>ContextualModMenuHost</code> unblocked (NativeMainMenuModMenu implemented)</li><li><code>PackUnitSpawner.OnUpdate()</code> completed (spawn queue + entity instantiation)</li><li><code>HotReloadBridge</code> entity update logic completed</li><li>Aviation namespace: decision and resolution</li></ul><hr><h2 id="current-stats-v0-12-0" tabindex="-1">Current Stats (v0.12.0+) <a class="header-anchor" href="#current-stats-v0-12-0" aria-label="Permalink to &quot;Current Stats (v0.12.0+)&quot;">​</a></h2><ul><li><strong>18 projects</strong> in the solution</li><li><strong>100+ tests passing</strong> (unit + integration, target 130+)</li><li><strong>17 schemas</strong> covering all content types</li><li><strong>6 example packs</strong> complete and playable (Modern, Star Wars, Guerrilla, Economy, Scenario, Balance)</li><li><strong>4 domain plugins</strong>: Warfare (✅ DONE), Economy, Scenario, UI</li><li><strong>21 MCP tools</strong> for Claude Code game automation</li><li><strong>8 CLI commands</strong> via <code>dinoforge</code> CLI + custom <code>.claude/commands/</code></li><li><strong>Autonomous video proof</strong> via Remotion + TTS + OmniParser</li></ul><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><blockquote><p>A new mod can be created mostly by editing validated pack files and running the toolchain, without new reverse engineering.</p></blockquote><p>If every mod still needs runtime surgery, the framework failed.</p>',76)])])}const g=i(r,[["render",l]]);export{u as __pageData,g as default};
